    bg = max({v for row in grid for v in row}, key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if color == bg:
                        continue
                    if any(grid[r0][x] != color or grid[r1][x] != color for x in range(c0, c1 + 1)):
                        continue
                    if any(grid[y][c0] != color or grid[y][c1] != color for y in range(r0, r1 + 1)):
                        continue
                    if any(grid[y][x] != bg for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)):
                        continue
                    fill = 2 if ((r1-r0-1) % 2 == 0 and (c1-c0-1) % 2 == 0) else 7
                    for y in range(r0 + 1, r1):
                        for x in range(c0 + 1, c1):
                            out[y][x] = fill
    for y in range(1, h - 1):
        for x in range(1, w - 1):
            color = grid[y - 1][x]
            if color != bg and grid[y][x] == bg and all(
                grid[yy][xx] == color for yy, xx in (
                    (y - 1, x - 1), (y - 1, x), (y - 1, x + 1),
                    (y, x - 1), (y, x + 1),
                    (y + 1, x - 1), (y + 1, x), (y + 1, x + 1))):
                out[y][x] = 7
    return out

